from typing import List, Optional
from pydantic import BaseModel, Field


class ValidationResult(BaseModel):
    """The structured validation report details generated by the Validation Agent."""
    validation_score: float = Field(description="Integrity validation score between 0.0 and 100.0.")
    confidence: float = Field(description="Agent audit confidence factor between 0.0 and 1.0.")
    description_quality: str = Field(description="Critique on copy structure, vocabulary, and educational style.")
    grammar_issues: List[str] = Field(description="Identified spelling or grammar issues.")
    readability_rating: str = Field(description="Readability index (e.g., Easy, Moderate, Advanced).")
    image_consistency: str = Field(description="Evaluation of prompt alignment with intake image properties.")
    issues: List[str] = Field(description="Aggregated list of problems or warnings found across fields.")
    recommendations: List[str] = Field(description="Actionable directions to fix the issues.")


class ValidationResponse(BaseModel):
    """Structured response wrap returned by the Validation Agent."""
    status: str = Field(description="Result of execution: 'success' or 'failed'.")
    errors: List[str] = Field(default_factory=list, description="List of processing error messages.")
    validation: Optional[ValidationResult] = Field(default=None, description="The validated validation details.")
